:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --primary: #6c63ff;
  --primary-hover: #5a52e0;
  --text: #f0f0f5;
  --text-muted: #a0a0b8;
  --lamp-off: #3a3a50;
  --lamp-on: #ffd166;
  --lamp-glow: 0 0 12px #ffd166;
  --focus: #ffd166;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  text-align: center;
  letter-spacing: 0.5px;
}

.subtitle {
  text-align: center;
  color: var(--text-muted);
  font-size: 0.95rem;
  margin-top: -12px;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.input-group label {
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--text-muted);
}

#decimalInput {
  font-size: 1.25rem;
  padding: 12px 16px;
  border-radius: 10px;
  border: 2px solid var(--lamp-off);
  background: var(--bg);
  color: var(--text);
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
  width: 100%;
}

#decimalInput:hover {
  border-color: var(--primary);
}

#decimalInput:focus-visible {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(255, 209, 102, 0.4);
}

.output-group {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.output-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg);
  padding: 12px 16px;
  border-radius: 10px;
}

.output-label {
  font-weight: 600;
  color: var(--text-muted);
  font-size: 0.95rem;
}

.output-value {
  font-family: 'SF Mono', 'Fira Code', 'Cascadia Code', monospace;
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--primary);
}

.lamps-fieldset {
  border: none;
  padding: 0;
  margin: 0;
}

.lamps-fieldset legend {
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--text-muted);
  margin-bottom: 8px;
  padding: 0;
}

.lamps {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
}

.lamp-btn {
  width: 48px;
  height: 56px;
  border-radius: 10px;
  border: 2px solid var(--lamp-off);
  background: var(--lamp-off);
  color: var(--text-muted);
  font-size: 0.8rem;
  font-weight: 700;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  cursor: pointer;
  transition: all 0.15s ease;
  outline: none;
  padding: 0;
  font-family: inherit;
}

.lamp-btn:hover {
  border-color: var(--primary);
  transform: scale(1.05);
}

.lamp-btn:focus-visible {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(255, 209, 102, 0.4);
}

.lamp-btn:active {
  transform: scale(0.95);
}

.lamp-btn[aria-pressed="true"] {
  background: var(--lamp-on);
  border-color: var(--lamp-on);
  color: #1e1e2f;
  box-shadow: var(--lamp-glow);
}

.lamp-btn[aria-pressed="true"]:hover {
  background: #ffdd88;
  border-color: #ffdd88;
}

.lamp-value {
  font-size: 0.7rem;
  opacity: 0.8;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .lamp-btn {
    width: 40px;
    height: 48px;
    font-size: 0.7rem;
  }
  .lamp-value {
    font-size: 0.6rem;
  }
  .output-value {
    font-size: 1.25rem;
  }
}

(function() {
  'use strict';

  const decimalInput = document.getElementById('decimalInput');
  const binaryOutput = document.getElementById('binaryOutput');
  const hexOutput = document.getElementById('hexOutput');
  const lampsContainer = document.getElementById('lampsContainer');

  const BIT_VALUES = [128, 64, 32, 16, 8, 4, 2, 1];
  let currentValue = 0;

  function clamp(n) {
    return Math.max(0, Math.min(255, n));
  }

  function toBinary(n) {
    return n.toString(2).padStart(8, '0');
  }

  function toHex(n) {
    return n.toString(16).toUpperCase().padStart(2, '0');
  }

  function updateDisplay() {
    decimalInput.value = currentValue;
    binaryOutput.textContent = toBinary(currentValue);
    hexOutput.textContent = toHex(currentValue);

    const buttons = lampsContainer.querySelectorAll('.lamp-btn');
    buttons.forEach(function(btn, index) {
      const bitValue = BIT_VALUES[index];
      const isOn = (currentValue & bitValue) !== 0;
      btn.setAttribute('aria-pressed', isOn ? 'true' : 'false');
      btn.setAttribute('aria-label', bitValue + ' bit, ' + (isOn ? 'on' : 'off'));
    });
  }

  function setValue(n) {
    currentValue = clamp(n);
    updateDisplay();
  }

  function buildLamps() {
    BIT_VALUES.forEach(function(bitValue, index) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'lamp-btn';
      btn.setAttribute('aria-pressed', 'false');
      btn.setAttribute('aria-label', bitValue + ' bit, off');
      btn.dataset.bit = bitValue;

      const valueSpan = document.createElement('span');
      valueSpan.className = 'lamp-value';
      valueSpan.textContent = bitValue;
      btn.appendChild(valueSpan);

      btn.addEventListener('click', function() {
        const bit = parseInt(btn.dataset.bit, 10);
        setValue(currentValue ^ bit);
      });

      lampsContainer.appendChild(btn);
    });
  }

  decimalInput.addEventListener('input', function() {
    const raw = decimalInput.value.trim();
    if (raw === '') {
      currentValue = 0;
      updateDisplay();
      return;
    }
    const parsed = parseInt(raw, 10);
    if (isNaN(parsed)) {
      currentValue = 0;
    } else {
      currentValue = clamp(parsed);
    }
    updateDisplay();
  });

  decimalInput.addEventListener('blur', function() {
    if (decimalInput.value.trim() === '' || isNaN(parseInt(decimalInput.value, 10))) {
      setValue(0);
    } else {
      setValue(parseInt(decimalInput.value, 10));
    }
  });

  buildLamps();
  updateDisplay();
})();
